import { test, expect } from '@playwright/test';

test.describe('File Upload Error Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/upload');
  });

  test('should display error for file exceeding maximum size limit', async ({ page }) => {
    const filePath = 'path/to/large/file.txt'; // Replace with a path to a file that exceeds the size limit
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: 'Upload' }));

    const errorMessage = await page.getByText('File size exceeds the maximum limit.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display error for valid file size', async ({ page }) => {
    const filePath = 'path/to/valid/file.txt'; // Replace with a path to a file that is within the size limit
    await page.setInputFiles(getByLabel('File Upload'), filePath);
    await page.click(getByRole('button', { name: 'Upload' }));

    const successMessage = await page.getByText('File uploaded successfully.');
    await expect(successMessage).toBeVisible();
  });
});
